CREATE OR REPLACE FUNCTION costing.fn_sku_activation_missing_items(p_sku_id bigint, p_product_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'costing', 'public', 'pg_temp'
AS $function$
declare
  v_product_id bigint;
  v_period date;
  v_val date;
  v_missing jsonb := '[]'::jsonb;
  v_family bigint;
  v_valid jsonb;
begin
  v_product_id := coalesce(p_product_id, (select s.product_id from public.product_skus s where s.id = p_sku_id));
  if v_product_id is null then
    raise exception 'SKU % not found', p_sku_id;
  end if;

  -- Current governed costing period = latest period; its valuation date is the as-of date.
  select cp.period_start, cp.valuation_date into v_period, v_val
  from costing.cost_periods cp order by cp.period_start desc limit 1;
  v_val := greatest(coalesce(v_val, current_date), (now() at time zone 'Asia/Kolkata')::date);  -- CI-038a

  -- (1) Approved PM-BOM revision (SKU level)
  if not exists (select 1 from public.plm_sku_bom_revision_as_of(p_sku_id, v_val) b where b.id is not null) then
    v_missing := v_missing || jsonb_build_object('code','PM_BOM_REVISION','label','Approved packing-material BOM','where','PM BOM Manager');
  end if;

  -- (2) Batch-size reference (product level)
  if not exists (select 1 from public.production_batch_size_ref b
                 where b.product_id = v_product_id and b.is_active
                   and b.effective_from <= v_val and (b.effective_to is null or b.effective_to >= v_val)) then
    v_missing := v_missing || jsonb_build_object('code','BATCH_SIZE_REFERENCE','label','Batch size reference','where','Batch Sizes (Supply / Batch Plan)');
  end if;

  -- (3) Production route READY (single-product version of costing.fn_product_process_route_readiness)
  v_family := costing.fn_resolve_route_family_for_product(v_product_id::int, v_val);
  v_valid  := costing.fn_validate_effective_product_process_route(v_product_id::int, v_val);
  if v_family is null
     or not exists (select 1 from costing.production_route_family_route r
                    where r.route_family_id = v_family and r.archived_at is null and r.status = 'APPROVED'
                      and r.effective_from <= v_val and (r.effective_to is null or r.effective_to >= v_val))
     or not coalesce((v_valid->>'valid')::boolean, false) then
    v_missing := v_missing || jsonb_build_object('code','MANUFACTURING_ROUTE','label','Production route','where','Production Route Manager');
  end if;

  -- (4) MRP policy
  if coalesce((select m.resolution_status from costing.fn_resolve_sku_mrp_as_of(p_sku_id, v_val) m limit 1), '') <> 'RESOLVED' then
    v_missing := v_missing || jsonb_build_object('code','MRP_POLICY','label','MRP policy','where','Pricing Policy Manager > MRP');
  end if;

  -- (5) Selling-price / GST policy
  if coalesce((select x.resolution_status from costing.fn_resolve_sku_selling_price_policy_as_of(p_sku_id, v_val) x limit 1), '') <> 'RESOLVED' then
    v_missing := v_missing || jsonb_build_object('code','SELLING_PRICE_POLICY','label','Selling price / GST policy','where','Pricing Policy Manager > Selling & scheme policies');
  end if;

  return jsonb_build_object('sku_id', p_sku_id, 'period_start', v_period, 'as_of_date', v_val, 'missing', v_missing);
end
$function$

CREATE OR REPLACE FUNCTION costing.fn_validate_effective_product_process_route(p_product_id integer, p_as_of_date date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'costing', 'public', 'pg_temp'
AS $function$
declare
  v_date date:=coalesce(p_as_of_date,current_date);
  v_family_id bigint;
  v_family_route_id bigint;
  v_product_route_id bigint;
  v_validation jsonb;
begin
  v_family_id:=costing.fn_resolve_route_family_for_product(p_product_id,v_date);
  if v_family_id is null then
    return jsonb_build_object('valid',false,'errors',jsonb_build_array('NO_APPROVED_ROUTE_FAMILY_MAPPING'),'route_source',null,'product_id',p_product_id);
  end if;

  v_family_route_id:=costing.fn_resolve_effective_route_family_route(p_product_id,v_date);
  if v_family_route_id is null then
    return jsonb_build_object('valid',false,'errors',jsonb_build_array('NO_APPROVED_ROUTE_FAMILY_ROUTE'),'route_source',null,'product_id',p_product_id,'route_family_id',v_family_id);
  end if;

  v_product_route_id:=costing.fn_resolve_effective_product_process_route(p_product_id,v_date);
  if v_product_route_id is not null then
    return costing.fn_validate_product_process_route(v_product_route_id)
      || jsonb_build_object('route_source','PRODUCT_ROUTE','product_id',p_product_id,'route_family_id',v_family_id,
                            'family_route_id',v_family_route_id,'product_route_id',v_product_route_id);
  end if;

  v_validation:=costing.fn_validate_route_family_route(v_family_route_id);
  return v_validation || jsonb_build_object(
    'route_source','ROUTE_FAMILY_INHERITED',
    'product_id',p_product_id,
    'route_family_id',v_family_id,
    'family_route_id',v_family_route_id,
    'product_route_id',null
  );
end
$function$

CREATE OR REPLACE FUNCTION costing.fn_wp04_build_readiness_portfolio(p_period_start date)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'costing', 'public', 'pg_temp'
AS $function$
DECLARE
  v_period date;
  v_val date;
  v_run bigint;
  v_build bigint;
  v_start_fp jsonb;
  v_start_digest text;
  v_end_fp jsonb;
  v_end_digest text;
  v_route_map jsonb;
  v_route_count bigint;
  v_route_distinct bigint;
  v_shared jsonb:='[]'::jsonb;
  v_sku_ids bigint[];
  v_run_map jsonb:='{}'::jsonb;
  v_items bigint;
  v_operational bigint;
  v_invalid bigint;
  v_relation record;
BEGIN
  v_period:=date_trunc('month',p_period_start::timestamp)::date;
  IF NOT pg_try_advisory_xact_lock(hashtextextended('WP04_READINESS_BUILD:'||v_period::text,0)) THEN
    RAISE EXCEPTION 'READINESS_BUILD_IN_PROGRESS';
  END IF;

  SELECT valuation_date INTO v_val
  FROM costing.cost_periods WHERE period_start=v_period;
  IF v_val IS NULL THEN RAISE EXCEPTION 'Governed valuation date missing for %',v_period; END IF;

  SELECT id INTO v_run
  FROM costing.costing_refresh_run
  WHERE period_start=v_period AND valuation_date=v_val AND overall_status='SUCCESS'
  ORDER BY finished_at DESC NULLS LAST,id DESC LIMIT 1;

  SELECT array_agg(id ORDER BY id) INTO v_sku_ids
  FROM public.product_skus;
  IF coalesce(cardinality(v_sku_ids),0)=0 THEN
    RAISE EXCEPTION 'No SKUs available for readiness build';
  END IF;

  SELECT fingerprint,digest INTO v_start_fp,v_start_digest
  FROM costing.fn_wp04_readiness_source_fingerprint(v_period);

  INSERT INTO costing.product_sku_readiness_portfolio_build(
    period_start,valuation_date,evidence_refresh_run_id,status,is_current,
    source_fingerprint,source_fingerprint_digest
  )
  VALUES(v_period,v_val,v_run,'BUILDING',false,v_start_fp,v_start_digest)
  RETURNING id INTO v_build;

  BEGIN
    WITH route_rows AS MATERIALIZED (
      SELECT * FROM costing.fn_product_process_route_readiness(v_val)
    )
    SELECT count(*),count(distinct product_id),jsonb_object_agg(product_id::text,to_jsonb(r))
    INTO v_route_count,v_route_distinct,v_route_map
    FROM route_rows r;

    IF v_route_count<>v_route_distinct THEN
      RAISE EXCEPTION 'Nonunique route evidence';
    END IF;

    IF v_run IS NOT NULL THEN
      v_shared:=costing.fn_product_sku_readiness_shared_issues(v_val);

      SELECT coalesce(jsonb_object_agg(c.sku_id::text,c.evidence_envelope),'{}'::jsonb)
      INTO v_run_map
      FROM costing.fn_wp04_c_run_cohort(v_sku_ids,v_period,v_val,v_run) c;

      IF (SELECT count(*) FROM jsonb_object_keys(v_run_map))<>cardinality(v_sku_ids) THEN
        RAISE EXCEPTION 'Batched run cohort cardinality mismatch';
      END IF;
    END IF;

    INSERT INTO costing.product_sku_readiness_portfolio_item(
      build_id,sku_id,product_id,product_name,product_status,
      sku_is_active,sku_is_sample,overall_severity,assessment
    )
    SELECT
      v_build,
      s.id,
      s.product_id,
      a.assessment#>>'{identity,product_name}',
      a.assessment#>>'{lifecycle,product_status}',
      coalesce((a.assessment#>>'{lifecycle,sku_is_active}')::boolean,false),
      coalesce((a.assessment#>>'{lifecycle,sku_is_sample}')::boolean,false),
      a.assessment#>>'{summary,overall_severity}',
      a.assessment
    FROM public.product_skus s
    CROSS JOIN LATERAL (
      SELECT costing.fn_wp04_c_live_core(
        s.id,v_period,v_val,v_run,
        v_route_map->(s.product_id::text),
        v_shared,
        CASE WHEN v_run IS NULL THEN NULL ELSE v_run_map->(s.id::text) END
      ) AS assessment
    ) a;

    SELECT count(*),
           count(*) FILTER(
             WHERE product_status='Active'
               AND sku_is_active
               AND NOT coalesce(sku_is_sample,false)
           ),
           count(*) FILTER(
             WHERE assessment#>>'{context,context_type}' IS DISTINCT FROM 'LIVE_AS_OF'
                OR assessment#>>'{context,sku_id}' IS DISTINCT FROM sku_id::text
                OR assessment#>>'{context,product_id}' IS DISTINCT FROM product_id::text
                OR assessment#>>'{context,period_start}' IS DISTINCT FROM v_period::text
                OR assessment#>>'{context,valuation_date}' IS DISTINCT FROM v_val::text
                OR assessment#>'{context,refresh_run_id}' IS DISTINCT FROM 'null'::jsonb
                OR (v_run IS NOT NULL AND assessment#>>'{context,evidence_refresh_run_id}' IS DISTINCT FROM v_run::text)
                OR overall_severity NOT IN ('READY','REVIEW_REQUIRED','BLOCKER','UNKNOWN')
           )
    INTO v_items,v_operational,v_invalid
    FROM costing.product_sku_readiness_portfolio_item
    WHERE build_id=v_build;

    IF v_items IS DISTINCT FROM cardinality(v_sku_ids) THEN
      RAISE EXCEPTION 'Readiness build item count mismatch';
    END IF;
    IF v_invalid<>0 THEN
      RAISE EXCEPTION 'Readiness build canonical validation failed for % items',v_invalid;
    END IF;

    INSERT INTO costing.product_sku_readiness_portfolio_incidence(
      build_id,sku_id,incidence_kind,dependency_code,issue_code,
      owner_module,route_code,status,shared_issue
    )
    SELECT i.build_id,i.sku_id,'DEPENDENCY',
           d->>'dependency_code',NULL,d->>'owner_module',d->>'recommended_ui_route',
           coalesce(d->>'effective_status',d->>'raw_status'),NULL
    FROM costing.product_sku_readiness_portfolio_item i
    CROSS JOIN LATERAL jsonb_array_elements(i.assessment->'dependencies') x(d)
    WHERE i.build_id=v_build
      AND d->>'applicability'<>'NOT_REQUIRED'
      AND coalesce(d->>'effective_status',d->>'raw_status')
          IN ('BLOCKED','BLOCKER','REVIEW_REQUIRED','UNKNOWN');

    INSERT INTO costing.product_sku_readiness_portfolio_incidence(
      build_id,sku_id,incidence_kind,dependency_code,issue_code,
      owner_module,route_code,status,shared_issue
    )
    SELECT i.build_id,i.sku_id,'SHARED',
           d->>'dependency_code',d->>'issue_code',d->>'owner_module',
           d->>'recommended_ui_route',d->>'status',d
    FROM costing.product_sku_readiness_portfolio_item i
    CROSS JOIN LATERAL jsonb_array_elements(i.assessment->'shared_issues') x(d)
    WHERE i.build_id=v_build
      AND d->>'status' IN ('BLOCKED','BLOCKER','REVIEW_REQUIRED','UNKNOWN');

    INSERT INTO costing.product_sku_readiness_portfolio_incidence(
      build_id,sku_id,incidence_kind,dependency_code,region_code,raw_status,effective_status
    )
    SELECT DISTINCT i.build_id,i.sku_id,'REGIONAL','REGIONAL_MARKETING_EVIDENCE',
           e->>'region_code',e->>'raw_status',e->>'effective_status'
    FROM costing.product_sku_readiness_portfolio_item i
    CROSS JOIN LATERAL jsonb_array_elements(i.assessment->'dependencies') x(d)
    CROSS JOIN LATERAL jsonb_array_elements(coalesce(d->'evidence','[]'::jsonb)) y(e)
    WHERE i.build_id=v_build
      AND d->>'dependency_code'='REGIONAL_MARKETING_EVIDENCE';

    FOR v_relation IN
      SELECT source_relation,epoch
      FROM costing.readiness_portfolio_source_epoch
      ORDER BY source_relation
      FOR UPDATE
    LOOP NULL; END LOOP;

    SELECT fingerprint,digest INTO v_end_fp,v_end_digest
    FROM costing.fn_wp04_readiness_source_fingerprint(v_period);

    IF v_end_digest IS DISTINCT FROM v_start_digest THEN
      UPDATE costing.product_sku_readiness_portfolio_build
      SET status='FAILED',completed_at=clock_timestamp(),error_text='SOURCE_CHANGED_DURING_BUILD'
      WHERE id=v_build;
      RETURN v_build;
    END IF;

    UPDATE costing.product_sku_readiness_portfolio_build
    SET is_current=false,
        status=CASE WHEN status='COMPLETED' THEN 'SUPERSEDED' ELSE status END
    WHERE period_start=v_period AND is_current;

    UPDATE costing.product_sku_readiness_portfolio_build
    SET status='COMPLETED',is_current=true,
        source_fingerprint=v_end_fp,source_fingerprint_digest=v_end_digest,
        item_count=v_items,operational_count=v_operational,
        completed_at=clock_timestamp(),promoted_at=clock_timestamp(),error_text=NULL
    WHERE id=v_build;

    RETURN v_build;
  EXCEPTION WHEN OTHERS THEN
    UPDATE costing.product_sku_readiness_portfolio_build
    SET status='FAILED',is_current=false,completed_at=clock_timestamp(),
        error_text=left(SQLSTATE||': '||SQLERRM,2000)
    WHERE id=v_build;
    RETURN v_build;
  END;
END
$function$

CREATE OR REPLACE FUNCTION public.fn_guard_active_sku_requires_active_product()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_product_status text;
begin
    if new.is_active is not true then
        return new;
    end if;

    select p.status
    into v_product_status
    from public.products p
    where p.id = new.product_id;

    if not found then
        raise exception
            'Cannot activate SKU: product % does not exist.',
            new.product_id;
    end if;

    if v_product_status is distinct from 'Active' then
        raise exception
            'Cannot activate SKU for inactive product %.',
            new.product_id;
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_guard_sku_activation_completeness()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'costing', 'pg_temp'
AS $function$
declare
  v_chk jsonb;
  v_list text;
begin
  if new.is_active is not true then return new; end if;
  if tg_op = 'UPDATE' and old.is_active is true then return new; end if;  -- already active: untouched

  v_chk := costing.fn_sku_activation_missing_items(new.id, new.product_id);
  if jsonb_array_length(v_chk->'missing') > 0 then
    select string_agg((m->>'label') || ' (' || (m->>'where') || ')', '; ')
      into v_list from jsonb_array_elements(v_chk->'missing') m;
    raise exception using
      errcode = 'P0001',
      message = format('Cannot activate SKU %s: missing %s. Fill these in, then activate again.', new.id, v_list),
      detail  = v_chk::text,
      hint    = 'Save the SKU as inactive until all five costing essentials are approved.';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.fn_log_product_sku_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_old jsonb := case when tg_op <> 'INSERT' then to_jsonb(old) end;
  v_new jsonb := case when tg_op <> 'DELETE' then to_jsonb(new) end;
  v_cols text[];
begin
  if tg_op = 'UPDATE' then
    select array_agg(k) into v_cols from jsonb_object_keys(v_new) k where v_new->k is distinct from v_old->k;
    if v_cols is null then return null; end if;   -- no-op update
  end if;
  insert into public.product_sku_change_log (sku_id, op, old_row, new_row, changed_columns, actor_user_id)
  values (coalesce((v_new->>'id')::bigint, (v_old->>'id')::bigint), tg_op, v_old, v_new, v_cols, auth.uid());
  return null;
end
$function$

CREATE OR REPLACE FUNCTION public.fn_product_skus_price_list_active_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NOT NEW.is_active THEN
    NEW.price_list_ik := FALSE;
    NEW.price_list_ok := FALSE;
  ELSE
    NEW.price_list_ik := COALESCE(NEW.price_list_ik,FALSE);
    NEW.price_list_ok := COALESCE(NEW.price_list_ok,FALSE);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_create_product(p_item text, p_sub_group_id integer, p_malayalam_name text, p_status text, p_uom_base text, p_conversion_to_base numeric, p_is_seasonal boolean, p_is_llt boolean, p_manufacture_lead_time_months integer, p_season_profile_id integer, p_is_pto boolean, p_reason text, p_approval_reference text DEFAULT NULL::text)
 RETURNS TABLE(product_id integer, item text, sub_group_id integer, malayalam_name text, status text, uom_base text, conversion_to_base numeric, is_seasonal boolean, is_llt boolean, manufacture_lead_time_months integer, season_profile_id integer, is_pto boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_actor uuid;
    v_item text;
    v_status text;
    v_uom_base text;
    v_reason text;
    v_approval_reference text;
    v_inserted public.products%rowtype;
begin
    perform public.require_permission(
        'module:manage-products',
        true
    );

    v_actor := auth.uid();

    if v_actor is null then
        raise exception 'Not authenticated';
    end if;

    v_item := btrim(coalesce(p_item, ''));
    v_status := initcap(lower(btrim(coalesce(p_status, ''))));
    v_uom_base := nullif(btrim(coalesce(p_uom_base, '')), '');
    v_reason := btrim(coalesce(p_reason, ''));
    v_approval_reference :=
        nullif(
            btrim(coalesce(p_approval_reference, '')),
            ''
        );

    if v_item = '' then
        raise exception 'Product name is required';
    end if;

    if v_reason = '' then
        raise exception 'Product creation reason is required';
    end if;

    if v_status not in ('Active', 'Inactive') then
        raise exception
            'Product status must be Active or Inactive';
    end if;

    if p_sub_group_id is null
       or not exists (
            select 1
            from public.sub_groups sg
            where sg.id = p_sub_group_id
       )
    then
        raise exception
            'Valid product subgroup is required';
    end if;

    if (
           v_uom_base is null
           and p_conversion_to_base is not null
       )
       or (
           v_uom_base is not null
           and p_conversion_to_base is null
       )
    then
        raise exception
            'Base UOM and conversion-to-base must either both be supplied or both be null';
    end if;

    if v_uom_base is not null
       and v_uom_base not in ('Kg', 'L', 'Nos')
    then
        raise exception
            'Base UOM must be Kg, L or Nos';
    end if;

    if p_conversion_to_base is not null
       and p_conversion_to_base <= 0
    then
        raise exception
            'Conversion-to-base must be greater than zero';
    end if;

    if p_manufacture_lead_time_months is not null
       and p_manufacture_lead_time_months < 0
    then
        raise exception
            'Manufacturing lead time cannot be negative';
    end if;

    if p_season_profile_id is not null
       and not exists (
            select 1
            from public.season_profile sp
            where sp.id = p_season_profile_id
       )
    then
        raise exception
            'Season profile % does not exist',
            p_season_profile_id;
    end if;

    perform pg_advisory_xact_lock(
        hashtext(
            'PRODUCT_NAME:'
            || public.normalize_key(v_item)
        )
    );

    if exists (
        select 1
        from public.products p
        where public.normalize_key(p.item)
            = public.normalize_key(v_item)
    ) then
        raise exception
            'A product with normalized name "%" already exists',
            public.normalize_key(v_item);
    end if;

    insert into public.products (
        item,
        sub_group_id,
        malayalam_name,
        status,
        uom_base,
        conversion_to_base,
        is_seasonal,
        is_llt,
        manufacture_lead_time_months,
        season_profile_id,
        is_pto
    )
    values (
        v_item,
        p_sub_group_id,
        nullif(
            btrim(coalesce(p_malayalam_name, '')),
            ''
        ),
        v_status,
        v_uom_base,
        p_conversion_to_base,
        coalesce(p_is_seasonal, false),
        coalesce(p_is_llt, false),
        p_manufacture_lead_time_months,
        p_season_profile_id,
        coalesce(p_is_pto, false)
    )
    returning *
    into v_inserted;

    insert into public.product_master_audit (
        product_id,
        event_type,
        old_snapshot,
        new_snapshot,
        reason,
        approval_reference,
        actor_user_id
    )
    values (
        v_inserted.id,
        'CREATE',
        null,
        to_jsonb(v_inserted),
        v_reason,
        v_approval_reference,
        v_actor
    );

    return query
    select
        v_inserted.id,
        v_inserted.item,
        v_inserted.sub_group_id,
        v_inserted.malayalam_name,
        v_inserted.status,
        v_inserted.uom_base,
        v_inserted.conversion_to_base,
        coalesce(v_inserted.is_seasonal, false),
        coalesce(v_inserted.is_llt, false),
        v_inserted.manufacture_lead_time_months,
        v_inserted.season_profile_id,
        v_inserted.is_pto;
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_create_product_sku(p_product_id bigint, p_pack_size numeric, p_uom text, p_is_active boolean, p_is_sample boolean, p_reason text, p_approval_reference text DEFAULT NULL::text)
 RETURNS TABLE(sku_id bigint, product_id bigint, pack_size numeric, uom text, is_active boolean, is_sample boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_actor uuid;
    v_uom text;
    v_reason text;
    v_approval_reference text;
    v_inserted public.product_skus%rowtype;
begin
    perform public.require_permission(
        'module:manage-products',
        true
    );

    v_actor := auth.uid();

    if v_actor is null then
        raise exception 'Not authenticated';
    end if;

    if p_product_id is null then
        raise exception 'Product ID is required';
    end if;

    if p_pack_size is null
       or p_pack_size <= 0
    then
        raise exception
            'SKU pack size must be greater than zero';
    end if;

    v_uom := btrim(coalesce(p_uom, ''));
    v_reason := btrim(coalesce(p_reason, ''));
    v_approval_reference :=
        nullif(
            btrim(coalesce(p_approval_reference, '')),
            ''
        );

    if v_uom = '' then
        raise exception 'SKU UOM is required';
    end if;

    if v_reason = '' then
        raise exception 'SKU creation reason is required';
    end if;

    if not exists (
        select 1
        from public.products p
        where p.id = p_product_id
    ) then
        raise exception
            'Product % does not exist',
            p_product_id;
    end if;

    perform pg_advisory_xact_lock(
        hashtext(
            'PRODUCT_SKU:'
            || p_product_id::text
            || ':'
            || p_pack_size::text
            || ':'
            || lower(v_uom)
        )
    );

    if exists (
        select 1
        from public.product_skus ps
        where ps.product_id = p_product_id
          and ps.pack_size = p_pack_size
          and lower(btrim(ps.uom)) = lower(v_uom)
    ) then
        raise exception
            'SKU already exists for product %, pack size % and UOM %',
            p_product_id,
            p_pack_size,
            v_uom;
    end if;

    insert into public.product_skus (
        product_id,
        pack_size,
        uom,
        is_active,
        is_sample
    )
    values (
        p_product_id,
        p_pack_size,
        v_uom,
        coalesce(p_is_active, false),
        coalesce(p_is_sample, false)
    )
    returning *
    into v_inserted;

    insert into public.product_sku_master_audit (
        sku_id,
        product_id,
        event_type,
        old_snapshot,
        new_snapshot,
        reason,
        approval_reference,
        actor_user_id
    )
    values (
        v_inserted.id,
        v_inserted.product_id,
        'CREATE',
        null,
        to_jsonb(v_inserted),
        v_reason,
        v_approval_reference,
        v_actor
    );

    return query
    select
        v_inserted.id,
        v_inserted.product_id,
        v_inserted.pack_size,
        v_inserted.uom,
        v_inserted.is_active,
        v_inserted.is_sample;
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_get_product_sku_readiness(p_sku_id bigint, p_period_start date, p_context_type text DEFAULT 'LIVE_AS_OF'::text, p_refresh_run_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'costing', 'pg_temp'
AS $function$
declare
 v_context_type text:=upper(coalesce(nullif(btrim(p_context_type),''),'LIVE_AS_OF'));
 v_period date; v_val date; v_run bigint; v_run_status text; v_integrity text:='LIVE_GOVERNED_PERIOD';
 v_route_json jsonb; v_shared_json jsonb;
 v_sku record; v_bom record; v_route record; v_mrp record; v_sell record; v_batch record; v_sales record; v_control record;
 v_pm text; v_sm text; v_cf text; v_ev text; v_out text; v_sev text; v_dep jsonb:='[]'; v_base jsonb;
begin

  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;
  if not (
    public.app_has_permission('module:manage-products', 'view')
    or public.app_has_permission('module:costing-control-center', 'view')
  ) then
    raise exception 'Permission denied for module:manage-products or module:costing-control-center (edit=false)';
  end if;

 if p_sku_id is null then raise exception 'SKU ID is required'; end if;
 if v_context_type not in ('LIVE_AS_OF','EXACT_RUN') then raise exception 'Invalid context type %',p_context_type; end if;
 select s.id sku_id,s.product_id,s.pack_size,s.uom,s.is_active sku_is_active,s.is_sample,p.item product_name,p.status product_status,p.uom_base,p.conversion_to_base
 into v_sku from public.product_skus s join public.products p on p.id=s.product_id where s.id=p_sku_id;
 if not found then raise exception 'SKU % not found',p_sku_id; end if;

 if v_context_type='LIVE_AS_OF' then
  if p_period_start is null then raise exception 'Costing period start is required for LIVE_AS_OF'; end if;
  v_period:=date_trunc('month',p_period_start::timestamp)::date;
  select valuation_date into v_val from costing.cost_periods where period_start=v_period;
  if v_val is null then raise exception 'Governed valuation date is missing for period %',v_period; end if;
  if p_refresh_run_id is not null then raise exception 'Refresh run ID is not accepted for LIVE_AS_OF'; end if;
  select id,overall_status into v_run,v_run_status from costing.costing_refresh_run
   where period_start=v_period and valuation_date=v_val and overall_status='SUCCESS'
   order by finished_at desc nulls last,id desc limit 1;
 else
  if p_refresh_run_id is null then raise exception 'Refresh run ID is required for EXACT_RUN'; end if;
  select r.id,r.period_start,r.valuation_date,r.overall_status,
   case when exists(select 1 from costing.costing_refresh_run_stage st where st.refresh_run_id=r.id and (st.period_start is distinct from r.period_start or st.valuation_date is distinct from r.valuation_date)) then 'MISMATCH'
        when r.valuation_context_source='LEGACY_BACKFILL' then 'LEGACY_UNVERIFIED' else 'CONSISTENT' end
  into v_run,v_period,v_val,v_run_status,v_integrity from costing.costing_refresh_run r where r.id=p_refresh_run_id;
  if v_run is null then raise exception 'Refresh run % not found',p_refresh_run_id; end if;
  if p_period_start is not null and date_trunc('month',p_period_start::timestamp)::date<>v_period then raise exception 'Supplied period does not match refresh run context'; end if;
 end if;

 if v_context_type='LIVE_AS_OF' then
  select to_jsonb(x) into v_route_json from costing.fn_product_process_route_readiness(v_val) x where x.product_id=v_sku.product_id limit 1;
  v_shared_json:='[]'::jsonb;
  if v_run is not null then v_shared_json:=costing.fn_product_sku_readiness_shared_issues(v_val); end if;
  return costing.fn_product_sku_readiness_live_core(p_sku_id,v_period,v_val,v_run,v_route_json,v_shared_json);
 end if;
  select * into v_control from costing.sku_costing_control_status_snapshot c where c.sku_id=p_sku_id and c.refresh_run_id=v_run limit 1;
  v_pm:='UNKNOWN'; v_sm:=case when v_control.sku_id is not null and v_control.pack_size>0 and nullif(btrim(v_control.pack_uom),'') is not null then 'RESOLVED' else 'UNKNOWN' end;
  v_cf:=case when v_control.sku_id is null then 'UNKNOWN' when v_control.cost_sheet_status='BLOCKED' then 'BLOCKED' else 'RESOLVED' end;
  v_ev:=case when v_control.sku_id is null then 'UNKNOWN' when v_control.control_severity='BLOCKER' then 'BLOCKED' when v_control.control_severity='REVIEW_REQUIRED' then 'REVIEW_REQUIRED' when v_control.control_severity='READY' then 'READY' else 'UNKNOWN' end;
  v_dep:=jsonb_build_array(
   jsonb_build_object('dependency_code','PRODUCT_MASTER','label','Product master','scope','PRODUCT','dimension','MASTER_FOUNDATION','applicability','APPLICABLE','raw_status','UNKNOWN','resolution_source','NOT_FROZEN_IN_RUN','reason_code','NOT_FROZEN_IN_RUN','owner_module','MANAGE_PRODUCTS','recommended_ui_route','MANAGE_PRODUCTS','authority','EXACT_RUN_FROZEN_EVIDENCE_ONLY'),
   jsonb_build_object('dependency_code','SKU_PACK_IDENTITY','label','SKU pack identity','scope','SKU_EXACT_RUN','dimension','MASTER_FOUNDATION','applicability','APPLICABLE','raw_status',v_sm,'resolution_source',case when v_control.sku_id is null then 'NO_RUN_SNAPSHOT' else 'RUN_CONTROL_SNAPSHOT' end,'owner_module','MANAGE_PRODUCTS','recommended_ui_route','MANAGE_PRODUCTS','authority','costing.sku_costing_control_status_snapshot'),
   jsonb_build_object('dependency_code','MRP_POLICY','label','MRP policy','scope','SKU_EXACT_RUN','dimension','COSTING_FOUNDATION','applicability','APPLICABLE','raw_status',case when v_control.mrp_resolution_status='RESOLVED' then 'RESOLVED' when v_control.sku_id is null then 'UNKNOWN' else 'BLOCKED' end,'resolution_source','RUN_CONTROL_SNAPSHOT','owner_module','PRICING_POLICY_MANAGER','recommended_ui_route','MRP_GOVERNANCE','authority','costing.sku_costing_control_status_snapshot'),
   jsonb_build_object('dependency_code','SELLING_PRICE_POLICY','label','Selling-price/GST policy','scope','SKU_EXACT_RUN','dimension','COSTING_FOUNDATION','applicability','APPLICABLE','raw_status',case when v_control.selling_policy_resolution_status='RESOLVED' then 'RESOLVED' when v_control.sku_id is null then 'UNKNOWN' else 'BLOCKED' end,'resolution_source','RUN_CONTROL_SNAPSHOT','owner_module','PRICING_POLICY_MANAGER','recommended_ui_route','SELLING_SCHEME_POLICIES','authority','costing.sku_costing_control_status_snapshot'),
   jsonb_build_object('dependency_code','FINAL_COSTING_CONTROL','label','Final costing control','scope','SKU_EXACT_RUN','dimension','COSTING_OUTCOME','applicability','APPLICABLE','raw_status',coalesce(v_control.cost_sheet_status,'UNKNOWN'),'resolution_source',case when v_control.sku_id is null then 'NO_RUN_SNAPSHOT' else 'RUN_CONTROL_SNAPSHOT' end,'reason_code',v_control.first_control_status,'note',v_control.control_note,'owner_module','COSTING_CONTROL_CENTER','recommended_ui_route',v_control.recommended_ui_route,'authority','costing.sku_costing_control_status_snapshot')
  );

 v_out:=coalesce(v_control.cost_sheet_status,'UNKNOWN');
 v_sev:=case when v_cf='BLOCKED' or v_ev='BLOCKED' or v_control.control_severity='BLOCKER' then 'BLOCKER' when v_ev='REVIEW_REQUIRED' or v_control.control_severity='REVIEW_REQUIRED' then 'REVIEW_REQUIRED' when v_control.control_severity='READY' then 'READY' else 'UNKNOWN' end;
 v_base:=jsonb_build_object(
  'context',jsonb_build_object('context_type',v_context_type,'sku_id',p_sku_id,'product_id',v_sku.product_id,'period_start',v_period,'valuation_date',v_val,'refresh_run_id',case when v_context_type='EXACT_RUN' then v_run else null end,'run_status',v_run_status,'context_integrity_status',v_integrity),
  'lifecycle',case when v_context_type='LIVE_AS_OF' then jsonb_build_object('product_status',v_sku.product_status,'sku_is_active',v_sku.sku_is_active,'sku_is_sample',v_sku.is_sample) else jsonb_build_object('status','UNKNOWN','reason_code','NOT_FROZEN_IN_RUN') end,
  'identity',jsonb_build_object('product_name',v_sku.product_name,'pack_size',case when v_context_type='EXACT_RUN' and v_control.sku_id is not null then v_control.pack_size else v_sku.pack_size end,'pack_uom',case when v_context_type='EXACT_RUN' and v_control.sku_id is not null then v_control.pack_uom else v_sku.uom end),
  'summary',jsonb_build_object('product_master_foundation_status',v_pm,'sku_master_foundation_status',v_sm,'costing_foundation_status',v_cf,'evidence_quality_status',v_ev,'costing_outcome_status',v_out,'overall_severity',v_sev),
  'dependencies',v_dep,'shared_issues','[]'::jsonb,
  'downstream_control',case when v_control.sku_id is null then null else jsonb_build_object('first_control_status',v_control.first_control_status,'control_severity',v_control.control_severity,'recommended_ui_route',v_control.recommended_ui_route,'control_note',v_control.control_note,'material_costing_status',v_control.material_costing_status,'pm_costing_status',v_control.pm_costing_status,'manufacturing_cop_status',v_control.manufacturing_cop_status,'internal_loaded_cost_status',v_control.internal_loaded_cost_status,'pricing_bridge_status',v_control.pricing_bridge_status,'selling_price_bridge_status',v_control.selling_price_bridge_status,'cost_sheet_status',v_control.cost_sheet_status,'refresh_run_id',v_control.refresh_run_id) end);
 if v_run is not null then return costing.fn_product_sku_readiness_enrich(v_base,p_sku_id,v_period,v_val,v_run); end if;
 return v_base;
end $function$

CREATE OR REPLACE FUNCTION public.rpc_get_product_sku_readiness_portfolio(p_period_start date, p_population_scope text DEFAULT 'OPERATIONAL'::text, p_overall_severities text[] DEFAULT NULL::text[], p_dependency_codes text[] DEFAULT NULL::text[], p_owner_modules text[] DEFAULT NULL::text[], p_route_codes text[] DEFAULT NULL::text[], p_search text DEFAULT NULL::text, p_after_sku_id bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'costing', 'pg_temp'
AS $function$
DECLARE
  v_period date;
  v_result jsonb;
  v_has_current boolean;
  v_current_status text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.app_has_permission('module:costing-control-center','view') THEN
    RAISE EXCEPTION 'Permission denied';
  END IF;
  IF p_period_start IS NULL THEN
    RAISE EXCEPTION 'Costing period start is required for LIVE_AS_OF';
  END IF;

  v_period:=date_trunc('month',p_period_start::timestamp)::date;

  -- One SQL statement/snapshot binds freshness, current-build identity and indexed read.
  SELECT costing.fn_wp04_readiness_portfolio_index_read(
           b.id,p_period_start,p_population_scope,p_overall_severities,
           p_dependency_codes,p_owner_modules,p_route_codes,p_search,p_after_sku_id,p_limit
         )
  INTO v_result
  FROM costing.fn_wp04_readiness_source_fingerprint(v_period) fp
  JOIN costing.product_sku_readiness_portfolio_build b
    ON b.period_start=v_period
   AND b.valuation_date=(fp.fingerprint->>'valuation_date')::date
   AND b.evidence_refresh_run_id IS NOT DISTINCT FROM
       nullif(fp.fingerprint->>'evidence_refresh_run_id','')::bigint
   AND b.status='COMPLETED'
   AND b.is_current
   AND b.source_fingerprint_digest=fp.digest
  ORDER BY b.id DESC
  LIMIT 1;

  IF v_result IS NOT NULL THEN
    RETURN v_result;
  END IF;

  SELECT EXISTS(
    SELECT 1
    FROM costing.product_sku_readiness_portfolio_build b
    WHERE b.period_start=v_period AND b.is_current
  )
  INTO v_has_current;

  IF NOT v_has_current THEN
    RAISE EXCEPTION 'READINESS_BUILD_ABSENT';
  END IF;

  SELECT status INTO v_current_status
  FROM costing.product_sku_readiness_portfolio_build
  WHERE period_start=v_period AND is_current
  ORDER BY id DESC LIMIT 1;

  IF v_current_status<>'COMPLETED' THEN
    RAISE EXCEPTION 'READINESS_BUILD_INCOMPLETE';
  END IF;

  RAISE EXCEPTION 'READINESS_BUILD_STALE';
END
$function$

CREATE OR REPLACE FUNCTION public.rpc_get_readiness_governed_periods(p_before_period_start date DEFAULT NULL::date, p_limit integer DEFAULT 24)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'costing', 'pg_temp'
AS $function$
declare result jsonb;
begin
 if auth.uid() is null then raise exception 'Not authenticated'; end if;
 if not public.app_has_permission('module:costing-control-center','view') then raise exception 'Permission denied'; end if;
 if p_limit is null or p_limit<1 or p_limit>100 then raise exception 'Invalid limit'; end if;
 with candidates as materialized (
  select period_start,valuation_date from costing.cost_periods
  where p_before_period_start is null or period_start<p_before_period_start
  order by period_start desc limit p_limit+1
 ), page as materialized (select * from candidates order by period_start desc limit p_limit)
 select jsonb_build_object('observed_at',statement_timestamp(),'before_period_start',p_before_period_start,'limit',p_limit,
  'rows',coalesce((select jsonb_agg(to_jsonb(p) order by period_start desc) from page p),'[]'::jsonb),
  'returned_count',(select count(*) from page),'has_more',(select count(*)>p_limit from candidates),
  'next_before_period_start',case when (select count(*)>p_limit from candidates) then (select min(period_start) from page) end)
 into result;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.rpc_set_product_sku_active(p_sku_id bigint, p_is_active boolean, p_reason text, p_approval_reference text DEFAULT NULL::text)
 RETURNS TABLE(sku_id bigint, product_id bigint, pack_size numeric, uom text, is_active boolean, is_sample boolean, audit_event_type text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_actor uuid;
    v_reason text;
    v_approval_reference text;
    v_event_type text;
    v_old public.product_skus%rowtype;
    v_new public.product_skus%rowtype;
    v_chk jsonb;
    v_list text;
begin
    perform public.require_permission('module:manage-products', true);
    v_actor := auth.uid();
    if v_actor is null then raise exception 'Not authenticated'; end if;
    if p_sku_id is null then raise exception 'SKU ID is required'; end if;
    if p_is_active is null then raise exception 'Target SKU active state is required'; end if;
    v_reason := btrim(coalesce(p_reason, ''));
    v_approval_reference := nullif(btrim(coalesce(p_approval_reference, '')), '');
    if v_reason = '' then raise exception 'SKU lifecycle reason is required'; end if;

    select * into v_old from public.product_skus ps where ps.id = p_sku_id for update;
    if not found then raise exception 'SKU % does not exist', p_sku_id; end if;
    if v_old.is_active is not distinct from p_is_active then
        raise exception 'SKU % is already %', p_sku_id, case when p_is_active then 'active' else 'inactive' end;
    end if;

    if p_is_active then
        v_chk := costing.fn_sku_activation_missing_items(p_sku_id, v_old.product_id);
        if jsonb_array_length(v_chk->'missing') > 0 then
            select string_agg(m->>'label', ', ') into v_list from jsonb_array_elements(v_chk->'missing') m;
            raise exception using errcode = 'P0001',
              message = format('This SKU cannot be made active yet. Missing: %s.', v_list),
              detail = v_chk::text;
        end if;
    end if;

    v_event_type := case when p_is_active then 'ACTIVATE' else 'DEACTIVATE' end;

    update public.product_skus ps set is_active = p_is_active where ps.id = p_sku_id returning * into v_new;

    insert into public.product_sku_master_audit (sku_id, product_id, event_type, old_snapshot, new_snapshot, reason, approval_reference, actor_user_id)
    values (v_new.id, v_new.product_id, v_event_type, to_jsonb(v_old), to_jsonb(v_new), v_reason, v_approval_reference, v_actor);

    return query select v_new.id, v_new.product_id, v_new.pack_size, v_new.uom, v_new.is_active, v_new.is_sample, v_event_type;
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_update_product(p_product_id integer, p_item text, p_sub_group_id integer, p_malayalam_name text, p_status text, p_uom_base text, p_conversion_to_base numeric, p_is_seasonal boolean, p_is_llt boolean, p_manufacture_lead_time_months integer, p_season_profile_id integer, p_is_pto boolean, p_reason text, p_approval_reference text DEFAULT NULL::text)
 RETURNS TABLE(product_id integer, item text, sub_group_id integer, malayalam_name text, status text, uom_base text, conversion_to_base numeric, is_seasonal boolean, is_llt boolean, manufacture_lead_time_months integer, season_profile_id integer, is_pto boolean, audit_event_type text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_actor uuid;
    v_item text;
    v_status text;
    v_uom_base text;
    v_reason text;
    v_approval_reference text;
    v_event_type text;
    v_old public.products%rowtype;
    v_new public.products%rowtype;
begin
    perform public.require_permission(
        'module:manage-products',
        true
    );

    v_actor := auth.uid();

    if v_actor is null then
        raise exception 'Not authenticated';
    end if;

    if p_product_id is null then
        raise exception 'Product ID is required';
    end if;

    v_item := btrim(coalesce(p_item, ''));
    v_status := initcap(lower(btrim(coalesce(p_status, ''))));
    v_uom_base := nullif(btrim(coalesce(p_uom_base, '')), '');
    v_reason := btrim(coalesce(p_reason, ''));
    v_approval_reference :=
        nullif(
            btrim(coalesce(p_approval_reference, '')),
            ''
        );

    if v_item = '' then
        raise exception 'Product name is required';
    end if;

    if v_reason = '' then
        raise exception 'Product update reason is required';
    end if;

    if v_status not in ('Active', 'Inactive') then
        raise exception
            'Product status must be Active or Inactive';
    end if;

    if p_sub_group_id is null
       or not exists (
            select 1
            from public.sub_groups sg
            where sg.id = p_sub_group_id
       )
    then
        raise exception
            'Valid product subgroup is required';
    end if;

    if (
           v_uom_base is null
           and p_conversion_to_base is not null
       )
       or (
           v_uom_base is not null
           and p_conversion_to_base is null
       )
    then
        raise exception
            'Base UOM and conversion-to-base must either both be supplied or both be null';
    end if;

    if v_uom_base is not null
       and v_uom_base not in ('Kg', 'L', 'Nos')
    then
        raise exception
            'Base UOM must be Kg, L or Nos';
    end if;

    if p_conversion_to_base is not null
       and p_conversion_to_base <= 0
    then
        raise exception
            'Conversion-to-base must be greater than zero';
    end if;

    if p_manufacture_lead_time_months is not null
       and p_manufacture_lead_time_months < 0
    then
        raise exception
            'Manufacturing lead time cannot be negative';
    end if;

    if p_season_profile_id is not null
       and not exists (
            select 1
            from public.season_profile sp
            where sp.id = p_season_profile_id
       )
    then
        raise exception
            'Season profile % does not exist',
            p_season_profile_id;
    end if;

    select *
    into v_old
    from public.products p
    where p.id = p_product_id
    for update;

    if not found then
        raise exception
            'Product % does not exist',
            p_product_id;
    end if;

    perform pg_advisory_xact_lock(
        hashtext(
            'PRODUCT_NAME:'
            || public.normalize_key(v_item)
        )
    );

    if exists (
        select 1
        from public.products p
        where p.id <> p_product_id
          and public.normalize_key(p.item)
              = public.normalize_key(v_item)
    ) then
        raise exception
            'Another product with normalized name "%" already exists',
            public.normalize_key(v_item);
    end if;

    if v_old.status is distinct from v_status then
        if v_status = 'Active' then
            v_event_type := 'ACTIVATE';
        else
            v_event_type := 'DEACTIVATE';
        end if;
    else
        v_event_type := 'UPDATE';
    end if;

    update public.products p
    set
        item = v_item,
        sub_group_id = p_sub_group_id,
        malayalam_name =
            nullif(
                btrim(coalesce(p_malayalam_name, '')),
                ''
            ),
        status = v_status,
        uom_base = v_uom_base,
        conversion_to_base = p_conversion_to_base,
        is_seasonal = coalesce(p_is_seasonal, false),
        is_llt = coalesce(p_is_llt, false),
        manufacture_lead_time_months =
            p_manufacture_lead_time_months,
        season_profile_id = p_season_profile_id,
        is_pto = coalesce(p_is_pto, false)
    where p.id = p_product_id
    returning *
    into v_new;

    insert into public.product_master_audit (
        product_id,
        event_type,
        old_snapshot,
        new_snapshot,
        reason,
        approval_reference,
        actor_user_id
    )
    values (
        v_new.id,
        v_event_type,
        to_jsonb(v_old),
        to_jsonb(v_new),
        v_reason,
        v_approval_reference,
        v_actor
    );

    return query
    select
        v_new.id,
        v_new.item,
        v_new.sub_group_id,
        v_new.malayalam_name,
        v_new.status,
        v_new.uom_base,
        v_new.conversion_to_base,
        coalesce(v_new.is_seasonal, false),
        coalesce(v_new.is_llt, false),
        v_new.manufacture_lead_time_months,
        v_new.season_profile_id,
        v_new.is_pto,
        v_event_type;
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_update_product_sku(p_sku_id bigint, p_pack_size numeric, p_uom text, p_is_sample boolean, p_reason text, p_approval_reference text DEFAULT NULL::text)
 RETURNS TABLE(sku_id bigint, product_id bigint, pack_size numeric, uom text, is_active boolean, is_sample boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_actor uuid;
    v_uom text;
    v_reason text;
    v_approval_reference text;
    v_old public.product_skus%rowtype;
    v_new public.product_skus%rowtype;
begin
    perform public.require_permission(
        'module:manage-products',
        true
    );

    v_actor := auth.uid();

    if v_actor is null then
        raise exception 'Not authenticated';
    end if;

    if p_sku_id is null then
        raise exception 'SKU ID is required';
    end if;

    if p_pack_size is null
       or p_pack_size <= 0
    then
        raise exception
            'SKU pack size must be greater than zero';
    end if;

    v_uom := btrim(coalesce(p_uom, ''));
    v_reason := btrim(coalesce(p_reason, ''));
    v_approval_reference :=
        nullif(
            btrim(coalesce(p_approval_reference, '')),
            ''
        );

    if v_uom = '' then
        raise exception 'SKU UOM is required';
    end if;

    if v_reason = '' then
        raise exception 'SKU update reason is required';
    end if;

    select *
    into v_old
    from public.product_skus ps
    where ps.id = p_sku_id
    for update;

    if not found then
        raise exception
            'SKU % does not exist',
            p_sku_id;
    end if;

    perform pg_advisory_xact_lock(
        hashtext(
            'PRODUCT_SKU:'
            || v_old.product_id::text
            || ':'
            || p_pack_size::text
            || ':'
            || lower(v_uom)
        )
    );

    if exists (
        select 1
        from public.product_skus ps
        where ps.id <> p_sku_id
          and ps.product_id = v_old.product_id
          and ps.pack_size = p_pack_size
          and lower(btrim(ps.uom)) = lower(v_uom)
    ) then
        raise exception
            'Another SKU already exists for product %, pack size % and UOM %',
            v_old.product_id,
            p_pack_size,
            v_uom;
    end if;

    update public.product_skus ps
    set
        pack_size = p_pack_size,
        uom = v_uom,
        is_sample = coalesce(p_is_sample, false)
    where ps.id = p_sku_id
    returning *
    into v_new;

    insert into public.product_sku_master_audit (
        sku_id,
        product_id,
        event_type,
        old_snapshot,
        new_snapshot,
        reason,
        approval_reference,
        actor_user_id
    )
    values (
        v_new.id,
        v_new.product_id,
        'UPDATE',
        to_jsonb(v_old),
        to_jsonb(v_new),
        v_reason,
        v_approval_reference,
        v_actor
    );

    return query
    select
        v_new.id,
        v_new.product_id,
        v_new.pack_size,
        v_new.uom,
        v_new.is_active,
        v_new.is_sample;
end;
$function$
